-- ---------------------------------------------------------------------------------
-- BUOC 2: Mo rong cot InBoxLabelList trong bang STB_HelaBarcodeOutBoxHist
--         Doi tu VARCHAR(1000) thanh VARCHAR(MAX) de chua duoc nhieu tem hon
-- LUU Y:  CHARACTER_MAXIMUM_LENGTH = -1 nghia la VARCHAR(MAX)
-- ---------------------------------------------------------------------------------
IF EXISTS (
    SELECT 1 
    FROM INFORMATION_SCHEMA.COLUMNS 
    WHERE TABLE_NAME = 'STB_HelaBarcodeOutBoxHist' 
      AND COLUMN_NAME = 'InBoxLabelList' 
      AND CHARACTER_MAXIMUM_LENGTH != -1
      AND CHARACTER_MAXIMUM_LENGTH < 4000
)
BEGIN
    PRINT N'Dang mo rong cot InBoxLabelList thanh VARCHAR(MAX)...'
    ALTER TABLE STB_HelaBarcodeOutBoxHist ALTER COLUMN InBoxLabelList VARCHAR(MAX) NULL; -- vanduc 2026-06-04: changed from VARCHAR(1000) to VARCHAR(MAX) to fix 80-barcode truncation
    PRINT N'Da mo rong thanh cong!'
END
ELSE
BEGIN
    PRINT N'Cot InBoxLabelList da du lon (VARCHAR(MAX) hoac >= 4000), khong can thay doi.'
END
GO

